import{_ as o,C as a,c as n,o as s,aj as l,G as r,w as d}from"./chunks/framework.Bfdr4H5E.js";const y=JSON.parse('{"title":"Deliberate Practice Tools and Techniques","description":"","frontmatter":{"outline":"deep","prev":{"text":"Deliberate Practice","link":"/trading-with-pav/deliberate-practice"},"next":{"text":"The Development Stages","link":"/trading-with-pav/the-development-stages"}},"headers":[],"relativePath":"trading-with-pav/deliberate-practice-tools-and-techniques.md","filePath":"trading-with-pav/deliberate-practice-tools-and-techniques.md"}'),c={name:"trading-with-pav/deliberate-practice-tools-and-techniques.md"};function p(h,e,u,m,f,g){const t=a("GraphComment"),i=a("ClientOnly");return s(),n("div",null,[e[0]||(e[0]=l('<h1 id="deliberate-practice-tools-and-techniques" tabindex="-1">Deliberate Practice Tools and Techniques <a class="header-anchor" href="#deliberate-practice-tools-and-techniques" aria-label="Permalink to &quot;Deliberate Practice Tools and Techniques&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#deliberate-practice-tools-and-techniques-1">Deliberate Practice Tools and Techniques</a><ul><li><a href="#defined-trading-procedures">Defined Trading Procedures</a></li><li><a href="#trading-logs-and-journals">Trading Logs and Journals</a></li><li><a href="#documented-review-process">Documented Review Process</a></li></ul></li><li><a href="#market-replay-bar-replay">Market Replay (Bar Replay)</a></li><li><a href="#market-replay-alternatives">Market Replay Alternatives</a></li><li><a href="#peer-review">Peer Review</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="deliberate-practice-tools-and-techniques-1" tabindex="-1">Deliberate Practice Tools and Techniques <a class="header-anchor" href="#deliberate-practice-tools-and-techniques-1" aria-label="Permalink to &quot;Deliberate Practice Tools and Techniques&quot;">​</a></h2><h3 id="defined-trading-procedures" tabindex="-1">Defined Trading Procedures <a class="header-anchor" href="#defined-trading-procedures" aria-label="Permalink to &quot;Defined Trading Procedures&quot;">​</a></h3><p>Defined trading procedures are the primary deliberate practice tool for the Trade stage (of our Trade-Record-Review-Improve cycle).</p><p><a href="/sk/trading-with-pav/trading-plan-template/">Article 79</a>, <a href="/sk/trading-with-pav/trading-plan-explanatory-notes/">80</a> documented our trading plan. <a href="/sk/trading-with-pav/procedures-manual/">Article 81</a> documented our trading procedures. By having clearly defined and documented procedures we ensure we minimize the likelihood of procedural error and maximize the likelihood of correct application of our trading strategy.</p><p>Our procedures manual also provides processes for ensuring we remain in a focused state with positive mindset.</p><p>Results will depend on our ability to correctly apply our plan and procedures; plus our level of expertise with regards to market analysis and decision making.</p><h3 id="trading-logs-and-journals" tabindex="-1">Trading Logs and Journals <a class="header-anchor" href="#trading-logs-and-journals" aria-label="Permalink to &quot;Trading Logs and Journals&quot;">​</a></h3><p><a href="/sk/trading-with-pav/additional-documentation/">Article 89</a> outlined the numerous trading logs and journals which we use to record observations and outcomes during our trading process.</p><p>These logs and journals are the primary tools for the Record stage (of our Trade-Record Review-Improve cycle), also featuring heavily during the Review stage.</p><p>Journals also offer the benefit of being easily accessible for further reading, whenever we have spare time.</p><h3 id="documented-review-process" tabindex="-1">Documented Review Process <a class="header-anchor" href="#documented-review-process" aria-label="Permalink to &quot;Documented Review Process&quot;">​</a></h3><p>Our procedures manual, outlined in <a href="/sk/trading-with-pav/procedures-manual/#sample-procedures-manual">article 81</a>, provided a sample session review procedure.</p><p>The primary aim of the session review is, in my opinion, carrying out a <strong>comparison between your performance and perfect performance</strong>. That is, looking at the session with the benefit of hindsight and asking some hard questions about both your read of the market environment and your ability to trade that environment.</p><p>This post-session review procedure is therefore the primary tool in achieving an effective Review stage (of our Trade-Record-Review-Improve cycle).</p><p>You may also wish to refer to the following pdf in <a href="/sk/ebooks/">eBooks</a>, titled, “How to Conduct an Effective Trading Session Review”:</p><p>The procedures manual also outlines processes for our longer-term reviews – monthly and annual.</p><p>The end result of the review process is a set of process goals for the next trading session; recorded in your trading log. This, hopefully applied with success in the next article, is the Improve part of your Trade-Record-Review-Improve cycle.</p><h2 id="market-replay-bar-replay" tabindex="-1">Market Replay (Bar Replay) <a class="header-anchor" href="#market-replay-bar-replay" aria-label="Permalink to &quot;Market Replay (Bar Replay)&quot;">​</a></h2><p>Our session review process also includes recommendations for use of a market replay feature, if your trading platform offers such a tool.</p><p>Market replay allows you to replay the trading session in a simulated environment. Price bars appear tick by tick, exactly as they did when trading live.</p><p>It will typically offer controls, as displayed below for play, pause and fast-forward, as well as a slide control to move to any particular chart time period.</p><p>We are also able to re-enter and manage trades all over again, this time in a simulated environment. This is an ideal tool for implementing deliberate practice.</p><p>Our post-session review allows us to identify error within our analysis or decision making. The market replay then allows us the opportunity to re-trade our setups again with the benefit of perfect hindsight; reinforcing correct behavior, enhancing our intuitive pattern recognition abilities, and advancing us further along our path of trader development.</p><p>While the exact price action will not occur again in future (every setup is unique), many very similar situations will occur over the remainder of my trading career.</p><p>Through taking these actions post session, I have reinforced the lessons from this trade, as well as experienced perfect trade entry and management.</p><p>And I have taken another small step forward in my development as a trader.</p><h2 id="market-replay-alternatives" tabindex="-1">Market Replay Alternatives <a class="header-anchor" href="#market-replay-alternatives" aria-label="Permalink to &quot;Market Replay Alternatives&quot;">​</a></h2><p>If your trading platform does not offer a market replay feature, I highly recommend you consider changing platforms.<br> However there are alternatives.</p><ol><li>Use video and audio screen capture software such as Camtasia, in order to record your live trades. This allows you to play back the video during your post-session review and compare your live trading decisions (supported by audio comments during the trade) with hindsight perfect trading decisions. However this does not allow for re-trading the setup, as available through market replay.</li><li>As a last resort, simply step bar by bar through your charts, either on the screen or on paper, reviewing your trading decisions from the perspective of your hindsight-perfect analysis. It’s not as good as market replay, but don’t discount it if this is all you can do. It’s still achieving deliberate practice – trading, seeking feedback, identifying the lessons, reinforcing correct behavior, and repeating.</li></ol><h2 id="peer-review" tabindex="-1">Peer Review <a class="header-anchor" href="#peer-review" aria-label="Permalink to &quot;Peer Review&quot;">​</a></h2><p>One further option you may wish to consider for enhancing your deliberate practice is peer review.</p><p>It requires that you create a trading group – a small number of traders (I‟d suggest 4 to 6) who act to support each other through the learning phase.</p><p>This is not something I have been involved in (at least not in a way which worked). It can be quite difficult to find the right group of people if you don’t already have a network of friends all interested in trading the same markets, timeframe and strategy.</p><p>However, if you do have an established network, or can create one, consider implementing the following review process.</p><p>After each session (if time allows), or at least one a week over the weekend, each person is to submit their journals to another member of the group for review and feedback.</p><p>You’ll learn from reviewing their work. And you’ll learn from reviewing the feedback they provide on your work.</p><p>As I said, it can be difficult to find the right group of people. I never did. But if you can achieve this I suspect it will be the next-best thing to having a personal mentor, and a whole lot cheaper.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',40)),r(i,null,{default:d(()=>[r(t)]),_:1})])}const w=o(c,[["render",p]]);export{y as __pageData,w as default};
